package dk.stream.android;

import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class CombinedCatalogTest {
 private Library.Source source(String id){return new Library.Source(id,id,"https://"+id+".example.com","user-"+id,"password-"+id,true,"");}
 private Playlist.Channel channel(String name,String group,Playlist.Kind kind,String series){return new Playlist.Channel(name,series==null?"https://example.com/"+name:"",group,kind,series,"");}
 @Test public void allSourcesShareOneListButKeepSourceIdentity(){Library.Source a=source("a"),b=source("b");Map<String,Catalog> data=new LinkedHashMap<>();data.put(a.id,new Catalog(Arrays.asList(channel("News A","News",Playlist.Kind.TV,null))));data.put(b.id,new Catalog(Arrays.asList(channel("News B","News",Playlist.Kind.TV,null))));CombinedCatalog combined=new CombinedCatalog(Arrays.asList(a,b),data);List<Library.Entry> rows=combined.filter(Playlist.Kind.TV,null,"");assertEquals(2,rows.size());assertEquals("a",rows.get(0).sourceId);assertEquals("b",rows.get(1).sourceId);assertEquals(Arrays.asList("News"),combined.catalog.groups(Playlist.Kind.TV));}
 @Test public void identicalSeriesIdsRemainDistinctBySource(){Library.Source a=source("a"),b=source("b");Catalog data=new Catalog(Arrays.asList(channel("Show","Drama",Playlist.Kind.SERIES,"42")));Map<String,Catalog> loaded=new HashMap<>();loaded.put("a",data);loaded.put("b",data);List<Library.Entry> rows=new CombinedCatalog(Arrays.asList(a,b),loaded).filter(Playlist.Kind.SERIES,null,"");assertEquals(2,rows.size());assertFalse(rows.get(0).same(rows.get(1)));Library library=new Library();library.toggleFavorite(rows.get(0));library.toggleFavorite(rows.get(1));assertEquals(2,library.favorites.size());}
 @Test public void groupsAndSearchIncludeEverySource(){Library.Source a=source("a"),b=source("b");Catalog first=new Catalog(Arrays.asList(channel("First","News",Playlist.Kind.TV,null)));Catalog second=new Catalog(Arrays.asList(channel("Second","Sport",Playlist.Kind.TV,null),channel("Movie","Drama",Playlist.Kind.FILM,null)));second.addGroup(Playlist.Kind.SERIES,"Series without loaded episodes");Map<String,Catalog> loaded=new HashMap<>();loaded.put("a",first);loaded.put("b",second);CombinedCatalog combined=new CombinedCatalog(Arrays.asList(a,b),loaded);assertEquals(Arrays.asList("News","Sport"),combined.catalog.groups(Playlist.Kind.TV));assertEquals("b",combined.filter(Playlist.Kind.TV,"Sport","second").get(0).sourceId);assertEquals(1,combined.filter(Playlist.Kind.FILM,null,"").size());assertEquals(1,combined.catalog.groups(Playlist.Kind.SERIES).size());}
 @Test public void missingOrRemovedSourcesDoNotHideOtherSources(){Library.Source a=source("a"),b=source("b");Map<String,Catalog> loaded=new HashMap<>();loaded.put("a",new Catalog(Arrays.asList(channel("A","",Playlist.Kind.TV,null))));CombinedCatalog combined=new CombinedCatalog(Arrays.asList(a,b),loaded);assertEquals(1,combined.filter(Playlist.Kind.TV,null,"").size());assertTrue(new CombinedCatalog(Arrays.asList(b),loaded).catalog.items.isEmpty());}
 @Test public void changedCredentialsInvalidateTheConnectionButRenamingDoesNot(){Library.Source a=source("a");assertTrue(CombinedCatalog.sameConnection(a,new Library.Source(a.id,"New label",a.server,a.username,a.password,a.xtream,"new-guide")));assertFalse(CombinedCatalog.sameConnection(a,new Library.Source(a.id,a.name,a.server,a.username,"changed",a.xtream,"")));assertFalse(CombinedCatalog.sameConnection(a,null));}
}
